// Probe-Observer Integration Tests
// =========================================================================

// Probes: 6 | Observers: 3 | Tests: 3
// All terminal nodes are observed.

/// Chain test: param_source_std_unicode_char_width_c -> std.unicode::char_width (depth 6)
/// 
/// Non-tautological: asserts observer matchers, not baseline values.
#[test]
fn test_chain_param_source_std_unicode_char_width_c_to_std_unicode_char_width() {
    if !guard_test("test_chain_param_source_std_unicode_char_width_c_to_std_unicode_char_width", TestClass::Unit, FermiCost::XS, &[], &[]) {
    return;
};
    let dag = gunbc_resolve::builder::build_dsl_graph_dag("std/unicode.dag", gunbc_resolve::BuildOpts::default()).expect("graph should build");
    let flat = lower(&dag).expect("lower should succeed").dag;
    let spec = mock_spec();
    // Full baseline DryRun to derive window entry inputs
    let baseline = execute_dag(&flat, ExecuteConfig { mode: ExecutionMode::DryRun(mock_spec().to_boundary_mocks()), ..Default::default() }).expect("baseline DryRun should succeed");
    let window = Window::from_nodes(&flat, vec!("param_source_std_unicode_char_display_width_c", "param_source_std_unicode_char_width_c", "std.unicode::char_display_width", "std.unicode::char_width", "std.unicode::code_point", "std.unicode::display_width_columns"));
    let mut mocks = spec.to_boundary_mocks();
    apply_window_inputs(&flat, &window, &baseline, &mut mocks).expect("chain entry inputs should be derivable from baseline");
    let window_dag = window_subdag(&flat, &window);
    let log = execute_dag(&window_dag, ExecuteConfig { mode: ExecutionMode::DryRun(mocks), ..Default::default() }).expect("chain execution should succeed");

    // Verify observer: std.unicode::char_width (depth 6)
    let mut matchers = HashMap::new();
    for ex in spec.node_examples.iter().filter(|e| e.node_id == "std.unicode::char_width") {
for (port, matcher) in &ex.outputs {
if matcher.is_chain_safe() {
matchers.insert(("std.unicode::char_width".to_string(), port.clone()), matcher.clone());
}
}
}
    for leo in spec.live_expected_outputs.iter().filter(|e| e.node == "std.unicode::char_width") {
if leo.matcher.is_chain_safe() {
matchers.insert(("std.unicode::char_width".to_string(), leo.port.clone()), leo.matcher.clone());
}
}
    assert_chain_outputs(&log, &matchers).expect("chain param_source_std_unicode_char_width_c -> std.unicode::char_width should satisfy observer matchers");
}

