// =========================================================================
// Node I/O Example Tests
// =========================================================================

// These tests verify individual node behavior against specified examples.
// Each test executes a single node with given inputs and checks outputs.

/// Node example: std.unicode::in_block (example 0)
/// 
/// Tests that node 'std.unicode::in_block' produces expected outputs for given inputs.
#[test]
fn test_example_std_unicode_in_block_0() {
    if !guard_test("test_example_std_unicode_in_block_0", TestClass::Unit, FermiCost::XS, &[], &[]) {
    return;
};
    let dag = gunbc_resolve::builder::build_dsl_graph_dag("std/unicode.dag", gunbc_resolve::BuildOpts::default()).expect("graph should build");
    let mut inputs = std::collections::HashMap::new();
    inputs.insert("__deps".to_string(), Value::List(vec![Value::Str("mock".to_string())]));
    inputs.insert("__out:return".to_string(), Value::Bool(true));
    inputs.insert("block".to_string(), Value::Map(std::collections::BTreeMap::from([("default_width".to_string(), Value::Enum { ty: "DisplayWidth".to_string(), variant: "ZeroWidth".to_string() }), ("end_inclusive".to_string(), Value::Int(1)), ("name".to_string(), Value::Str("example".to_string())), ("start".to_string(), Value::Int(1))])));
    inputs.insert("cp".to_string(), Value::Int(1));
    inputs.insert("return".to_string(), Value::Bool(true));
    let outputs = gunbc_exec::execute_single_node(&dag, "std.unicode::in_block", inputs, gunbc_exec::ExecutionMode::Real).expect("node 'std.unicode::in_block' should execute successfully");

    // Check output port 'return'
    let output_return = outputs.get("return").expect("output port 'return' should exist");
    assert!(output_return.as_bool().is_some() || matches!(*output_return, Value::Skipped), "expected Bool or Skipped for output_return");
}

